async function loadResetPanel(role,student,batch,draw){const panel=$('#activeAccounts');panel.textContent='Pobieranie loginów…';try{const result=await callSchool('create-school-account',{action:'list',role});if(!panel.isConnected)return;const accounts=result.accounts;panel.innerHTML=`<section><h2>Istniejące konta – ${esc(roles[role])}</h2><p>Zaznacz konta do zmiany. UID pozostaje bez zmian. Konta z rzeczywistym e-mailem wymagają ręcznej obsługi.</p><label><input type="checkbox" id="selectAll35"> Zaznacz wszystkie dostępne</label><div style="overflow:auto"><table><thead><tr><th>Wybór</th><th>Imię i nazwisko</th><th>Login</th><th>Wynik</th><th>Usuń konto</th></tr></thead><tbody>${accounts.map((a,i)=>`<tr><td><input type="checkbox" data-account="${i}" ${a.eligible?'':'disabled'}></td><td>${esc(a.name)}</td><td data-login="${i}">${esc(a.login||'Brak konta Auth')}</td><td data-result="${i}">${a.eligible?'—':'Niedostępne'}</td><td><button data-delete36="${i}">Usuń konto</button></td></tr>`).join('')}</tbody></table></div><button id="resetSelected35">Generuj nowe loginy i hasła</button><p id="resetProgress35" role="status"></p></section>`;
panel.querySelectorAll('[data-delete36]').forEach(b=>b.onclick=async()=>{if(resetBusy)return;const a=accounts[Number(b.dataset.delete36)];if(prompt('Usunąć konto '+a.name+'? Wpisz USUŃ. Dane ucznia pozostaną bez konta.')!=='USUŃ')return;b.disabled=true;try{await req(db.rpc('ed_delete_account36',{target:a.id}));const j=batch.findIndex(x=>x.id===a.id);if(j>=0)batch.splice(j,1);draw();await load();await loadResetPanel(role,student,batch,draw);notice('Usunięto konto.')}catch(e){notice(e.message);b.disabled=false}});
const checks=[...panel.querySelectorAll('[data-account]:not(:disabled)')];const all=panel.querySelector('#selectAll35');all.onchange=()=>checks.forEach(c=>c.checked=all.checked);checks.forEach(c=>c.onchange=()=>{all.checked=checks.length>0&&checks.every(x=>x.checked)});
const button=panel.querySelector('#resetSelected35');button.onclick=async()=>{if(resetBusy)return;const selected=checks.filter(c=>c.checked);if(!selected.length)return notice('Zaznacz konta.');if(!confirm(`Zmienić dane logowania ${selected.length} kont? Zapisz lub wydrukuj nowe hasła przed odświeżeniem.`))return;resetBusy=true;button.disabled=true;const nav=[...document.querySelectorAll('#nav button,#logout,#generate button,[data-delete36]')];nav.forEach(b=>b.disabled=true);checks.forEach(c=>c.disabled=true);all.disabled=true;let ok=0,fail=0;try{for(const c of selected){const i=Number(c.dataset.account),a=accounts[i],status=panel.querySelector(`[data-result="${i}"]`);try{let r;for(let attempt=0;attempt<5;attempt++){try{r=await callSchool('create-school-account',{action:'reset',id:a.id});break}catch(e){if(attempt===4||!/already|registered|duplicate|exists/i.test(e.message))throw e;}}const old=batch.findIndex(x=>x.id===a.id);if(old>=0)batch.splice(old,1);batch.push({id:a.id,name:r.name,className:student?name('classes',D.students.find(x=>x.account===a.id)?.class_id):'',login:r.login,password:r.password});panel.querySelector(`[data-login="${i}"]`).textContent=r.login;status.textContent='Zmieniono';c.checked=false;ok++;draw();}catch(e){status.textContent='Błąd: '+e.message;fail++;}panel.querySelector('#resetProgress35').textContent=`Zmieniono: ${ok}, błędy: ${fail}, razem: ${selected.length}`;}}finally{resetBusy=false;button.disabled=false;nav.forEach(b=>b.disabled=false);checks.forEach(c=>c.disabled=false);all.disabled=false;all.checked=checks.every(c=>c.checked);notice(`Zmieniono ${ok} kont. Błędy: ${fail}. Wydrukuj nowe dane.`);}};
}catch(e){panel.textContent='Nie udało się pobrać kont: '+e.message;}}

async function callSchool(fn,body){const {data,error}=await db.functions.invoke(fn,{body});if(error){let msg=error.message;try{msg=(await error.context.json()).error||msg}catch{}throw Error(msg);}if(!data?.success)throw Error(data?.error||'Niepowodzenie funkcji');return data;}
function showPasswordChange(){ $('#shell').hidden=true;$('#login').hidden=false;$('#logout').hidden=false;$('#login').innerHTML=`<form id="firstPassword"><h1>Ustaw nowe hasło</h1><p>Hasło początkowe należy zmienić przed dostępem do dziennika.</p><label>Nowe hasło (minimum 6 znaków)<input type="password" name="password" minlength="6" maxlength="72" autocomplete="new-password" required></label><label>Powtórz hasło<input type="password" name="repeat" minlength="6" autocomplete="new-password" required></label><button>Zapisz nowe hasło</button></form>`;bind('firstPassword',async v=>{if(v.password!==v.repeat)throw Error('Hasła nie są identyczne.');await callSchool('change-school-password',{password:v.password});await db.auth.signOut();alert('Hasło zmienione. Zaloguj się ponownie nowym hasłem.');location.reload();});}


const documents=[['Rezygnacja z religii','Proszę o zaprzestanie uczestnictwa ucznia w zajęciach religii od dnia:'],['Wniosek o zwolnienie z WF','Wnoszę o zwolnienie z wykonywania ćwiczeń lub zajęć WF w zakresie i okresie określonym w załączonej opinii lekarza. Zakres i okres:'],['Wniosek o organizację nauki ze względu na zdrowie','Proszę o rozpatrzenie możliwości organizacji nauki indywidualnej lub zdalnej zgodnie z właściwymi przepisami i wymaganymi dokumentami. Proponowany okres i potrzeby:'],['Wniosek o wsparcie psychologiczne','Proszę o objęcie ucznia pomocą psychologiczno-pedagogiczną. Preferowany zakres wsparcia:'],['Wniosek o pomoc w nauce','Proszę o wsparcie w związku z trudnościami w nauce. Przedmioty i potrzeby:'],['Informacja żywieniowa i alergie','Produkty do wykluczenia, alergie, nietolerancje, zalecenia żywieniowe i sposób kontaktu w razie potrzeby:'],['Zapis na obiady szkolne','Proszę o zapisanie ucznia na obiady. Data rozpoczęcia i dni tygodnia:'],['Zapis na zajęcia dodatkowe','Proszę o zapisanie ucznia na koło zainteresowań lub zajęcia dodatkowe. Nazwa i termin:'],['Wniosek o dodatkowe korepetycje','Proszę o rozpatrzenie możliwości dodatkowych zajęć wyrównawczych lub konsultacji pozaszkolnych. Przedmiot i preferowane terminy:']];
